\section{Notation and standing definitions}

All statistical functionals are \emph{empirical} (finite-population) functionals; no probability space beyond a finite uniform one is required.

\begin{definition}[Empirical functionals]
For $f,g:\{1,\dots,n\}\to\mathbb{R}$ put
\[
\bar f = \tfrac1n\sum_i f(i),\qquad
\Var(f) = \tfrac1n\sum_i (f(i)-\bar f)^2,\qquad
\Cov(f,g) = \tfrac1n\sum_i (f(i)-\bar f)(g(i)-\bar g).
\]
\end{definition}

\begin{definition}[Interval]
A \emph{confidence interval} is a pair $I=[\ell,h]$ with $\ell\le h$; its \emph{centre} is $c(I) = (\ell+h)/2$, its \emph{half-width} $w(I) = (h-\ell)/2$; it \emph{covers} $x$ iff $\ell\le x\le h$; its \emph{edge deliverable} is $E(I) = \max(|\ell-1|,|h-1|)$.
\end{definition}

\begin{definition}[Two-level design]
A \emph{balanced two-level design} is an array $x:\{1,\dots,m\}\times\{1,\dots,n\}\to\mathbb{R}$. With $\bar x_i$ the $i$-th cluster mean and $\bar{\bar x}$ the grand mean, set
\[
V_{\mathrm{within}} = \tfrac1m\sum_i \Var(x_{i\cdot}),\qquad
V_{\mathrm{between}} = \Var(\bar x_\cdot),\qquad
V_{\mathrm{total}} = \tfrac1{mn}\sum_{i,j}(x_{ij}-\bar{\bar x})^2 .
\]
\end{definition}

\begin{definition}[Resample space]
The \emph{cluster-bootstrap resample space} on $m$ clusters is the set of all $m^m$ maps $s:\{1,\dots,m\}\to\{1,\dots,m\}$, each equally likely. The resample mean of cluster values $c_1,\dots,c_m$ is $\bar c^{(s)} = \frac1m\sum_k c_{s(k)}$, and
\[
\Var_{\mathrm{boot}}(c) = \frac{1}{m^m}\sum_{s}\bigl(\bar c^{(s)}-\bar c\bigr)^2 .
\]
\end{definition}

\section{The reporting scheme: exact anatomy of the deliverable}

\begin{lemma}\label{lem:cover}
$I$ covers $x$ if and only if $|x - c(I)| \le w(I)$.
\end{lemma}
\begin{proof}
Substitute $\ell = c-w$, $h = c+w$ and split the absolute value; both sides reduce to $\ell\le x\le h$.
\end{proof}

\begin{theorem}[Edge Decomposition]\label{thm:edge}
If $I$ covers $1$, then $E(I) = w(I) + |c(I)-1|$.
\end{theorem}
\begin{proof}
Write $c=c(I)$, $w=w(I)$; coverage gives $c-w\le 1\le c+w$. If $c\ge 1$ then $|h-1| = c+w-1$ while $|\ell-1| = 1-c+w \le c+w-1$, so $E = c+w-1 = w + |c-1|$. If $c\le 1$ the roles exchange symmetrically.
\end{proof}

\begin{remark}
A study's headline number is the sum of two logically independent virtues: precision (small $w$) and absence of drift (small $|c-1|$). Two studies can share an edge deliverable while being scientifically incomparable; the decomposition makes the comparison auditable.
\end{remark}

\begin{corollary}[Domination]
If $I$ and $J$ both cover $1$, $w(I)\le w(J)$ and $|c(I)-1| \le |c(J)-1|$, then $E(I)\le E(J)$.
\end{corollary}

\begin{proposition}\label{prop:tighten}
The pilot interval $[0.8630,1.0389]$ has $E = 0.1370$; the replication interval $[0.919,1.0101]$ has $E = 0.0810$. Moreover
\[
w(\mathrm{rep}) = 0.04555 < 0.08795 = w(\mathrm{pilot}),\qquad
|c(\mathrm{rep})-1| = 0.03545 < 0.04905 = |c(\mathrm{pilot})-1| .
\]
Hence the tightening is not an artefact of re-centring: both summands strictly improve.
\end{proposition}

\begin{proposition}[Null branch selected]
All three reported intervals cover $1$.
\end{proposition}

\section{The price of direction stability}

\begin{lemma}
Exactly $2$ of the $2^k$ sign patterns $e:\{1,\dots,k\}\to\{\pm\}$ are constant, for $k\ge1$.
\end{lemma}
\begin{proof}
A constant pattern is determined by its value at index $1$, and the two candidates $e\equiv+$, $e\equiv-$ are distinct.
\end{proof}

\begin{theorem}[Direction-stability $p$-value]\label{thm:dir}
Under the null hypothesis that each split-half sign is an independent fair coin, the probability that $k$ split-halves all agree is $p_k = 2/2^k = 2^{1-k}$.
\end{theorem}

\begin{corollary}
$p_4 = 1/8 > 1/20$: four agreeing split-halves are not significant at the $5\%$ level.
\end{corollary}

\begin{corollary}[Depth needed]
$2^{1-k}\le 1/20$ if and only if $k\ge 6$.
\end{corollary}
\begin{proof}
For $k\le 5$, $2/2^k\ge 1/16 > 1/20$; for $k\ge 6$, $2^k\ge 64$ so $2/2^k \le 1/32 < 1/20$.
\end{proof}

\section{Arithmetic of the candidate pool: why the null is structural}

\subsection{Local densities}

\begin{theorem}[Local density]\label{thm:locdens}
For $p$ an odd prime and $N\in\mathbb{Z}$, the number of residues $j \bmod p$ with $p \mid j^2 - N$ equals $1 + \Leg{N}{p}$. Hence the candidate local density is
\[
\delta_p(N) = \frac{1+\Leg{N}{p}}{p}.
\]
\end{theorem}
\begin{proof}
The equation $x^2 = N$ in $\mathbb{F}_p$ ($p$ odd) has $2$, $1$ or $0$ solutions according as $N$ is a nonzero square, zero, or a non-square; the count is $1+\Leg{N}{p}$ in all three cases.
\end{proof}

\begin{corollary}[Extreme local deviation]
For $p\nmid N$, $\delta_p(N) = 2/p$ if $N$ is a quadratic residue mod $p$ and $\delta_p(N)=0$ otherwise, against the control density $1/p$. The relative deviation is $\pm 100\%$ at \emph{every} prime: there is no small-perturbation regime.
\end{corollary}

\begin{theorem}[Two-class average]\label{thm:twoclass}
If $\Leg{N_1}{p} = +1$ and $\Leg{N_2}{p} = -1$ then $\tfrac12(\delta_p(N_1)+\delta_p(N_2)) = 1/p$, exactly the control density.
\end{theorem}

\begin{remark}
This is the structural content of the null hypothesis. The candidate pool is not random at any prime, but its non-randomness is a \emph{rearrangement across the population of moduli}, with exact first-order cancellation. Any global drift must come from a higher-order or non-local mechanism.
\end{remark}

\subsection{The multiplicative bias and its exponential variance}

Model the aggregate bias of a single modulus across $k$ small primes by
\[
\Pi(e) = \prod_{i=1}^k (1+\varepsilon_i),\qquad \varepsilon_i = \pm1,
\]
the $2^k$ sign vectors being equally likely; by Theorem~\ref{thm:locdens}, $1+\varepsilon_i$ is the ratio $\delta_{p_i}(N)\big/(1/p_i)$.

\begin{theorem}[Moments of the bias]\label{thm:bias}
$\sum_e \Pi(e) = 2^k$ and $\sum_e \Pi(e)^2 = 4^k$; hence $\mathbb{E}[\Pi]=1$, $\mathbb{E}[\Pi^2]=2^k$, and
\[
\Var(\Pi) = 2^k - 1 .
\]
\end{theorem}
\begin{proof}
Both sums factor coordinatewise: $\prod_i((1+1)+(1-1)) = 2^k$ and $\prod_i(4+0) = 4^k$. Divide by $2^k$ and subtract the squared mean.
\end{proof}

\begin{corollary}[Effective sample size is the cluster count]
The variance-to-mean-square ratio of the per-modulus bias grows like $2^k$, so a bootstrap treating the $19.2\times10^6$ pairs as exchangeable understates the spread by that exponentially large factor; only resampling whole $N$-clusters is consistent.
\end{corollary}

\begin{remark}
Concretely, $\Pi$ equals $2^k$ on the single all-residue sign pattern and $0$ on the other $2^k-1$: the bias distribution is maximally heavy-tailed --- a lottery, not a jitter.
\end{remark}

\section{Exact local independence, and the isolation of the remaining heuristic}

\begin{definition}
For $p\ge1$ and $N\in\mathbb{Z}$, the \emph{survivor count} is $M_p(N) = \#\{j\bmod p : p\nmid j^2-N\}$ and the \emph{survival density} is $\mu_p(N) = M_p(N)/p$.
\end{definition}

\begin{lemma}
For $p$ an odd prime, $M_p(N) = p - \bigl(1+\Leg{N}{p}\bigr)$, so $\mu_p(N) = 1-\delta_p(N)$.
\end{lemma}

\begin{theorem}[Exact splitting of paired congruence conditions]\label{thm:crt}
Let $a,b\ge1$ be coprime, let $P$ be any predicate on residues mod $a$ and $Q$ any predicate on residues mod $b$. Then
\[
\#\{\,j \bmod ab : P(j\bmod a) \text{ and } Q(j \bmod b)\,\}
= \#\{x\bmod a: P(x)\}\cdot\#\{y \bmod b : Q(y)\}.
\]
\end{theorem}
\begin{proof}
The Chinese Remainder Theorem gives a ring isomorphism $\mathbb{Z}/ab \cong \mathbb{Z}/a\times\mathbb{Z}/b$ whose two components are precisely the reduction maps; it carries the set on the left bijectively onto $\{x:P(x)\}\times\{y:Q(y)\}$, and the cardinality of a product is the product of cardinalities.
\end{proof}

\begin{corollary}[Exact local independence]\label{cor:crtprod}
For coprime $a,b$,
\[
\#\{\,j\bmod ab : a\nmid j^2-N \text{ and } b \nmid j^2-N\,\} = M_a(N)M_b(N),
\]
with no error term; and for any finite set $P$ of pairwise coprime moduli with product $\Pi_P$,
\[
\#\bigl\{\,j \bmod \Pi_P : p \nmid j^2-N \text{ for all } p \in P\,\bigr\} = \prod_{p\in P}M_p(N).
\]
Equivalently, the local survival densities multiply exactly.
\end{corollary}
\begin{proof}
The two-modulus case is Theorem~\ref{thm:crt} applied to the two survival predicates, divisibility of $j^2-N$ by a divisor of $ab$ being determined by the corresponding component; the general case follows by induction on $|P|$.
\end{proof}

\begin{proposition}[Per-prime discrepancy]
For $p$ an odd prime, $\mu_p(N) - (1-1/p) = -\Leg{N}{p}/p$, of magnitude exactly $1/p$ and of either sign.
\end{proposition}

\begin{remark}
The Dickman-style argument has two steps: (i) multiplicativity of the local survival conditions; (ii) the passage from a finite prime set to full $B$-smoothness. Corollary~\ref{cor:crtprod} establishes (i) \emph{exactly}. Any failure of the shifted-square heuristic must therefore be a failure of the finite-to-full passage.
\end{remark}

\section{Cluster inference: the exact variance theory}

\subsection{Why pairing is the right control design}

\begin{theorem}[Contrast variance]
For empirical sequences $X,Y$ over $n$ units,
$\Var(X-Y) = \Var(X)+\Var(Y)-2\Cov(X,Y)$, and $\Cov(X,Y)^2 \le \Var(X)\Var(Y)$.
\end{theorem}

\begin{corollary}
Pairing strictly beats independent sampling exactly when the induced empirical covariance is positive.
\end{corollary}

\begin{proposition}[Indicator case]
If $X,Y$ are $\{0,1\}$-valued with means $p,q$, then $\Var(X)=p(1-p)$ and $\Cov(X,Y) = \frac1n\#\{i: X_i=Y_i=1\} - pq$. Hence the paired contrast of two rare events (here $p,q\approx 3\times10^{-5}$) has variance essentially $p+q-2\cdot(\text{joint hit rate})$; in the degenerate extreme of a perfectly predictive pairing, $\Var(X-X)=0$.
\end{proposition}

\subsection{The ANOVA floor}

\begin{lemma}[Shift identity]\label{lem:shift}
For any $f$ on $n$ units and any $c\in\mathbb{R}$,
$\sum_j (f(j)-c)^2 = \sum_j (f(j)-\bar f)^2 + n(\bar f - c)^2$.
Consequently $\Var(f)$ is the minimum over centres of $\frac1n\sum_j (f(j)-c)^2$.
\end{lemma}

\begin{theorem}[Balanced ANOVA decomposition]\label{thm:anova}
For a balanced two-level design, $V_{\mathrm{total}} = V_{\mathrm{within}} + V_{\mathrm{between}}$.
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:shift} inside each cluster with $c = \bar{\bar x}$, sum over clusters and divide by $mn$.
\end{proof}

\begin{corollary}[Between-cluster floor]
$V_{\mathrm{between}}\le V_{\mathrm{total}}$; hence for any target $t \le V_{\mathrm{between}}$ one also has $t \le V_{\mathrm{total}}$. Whatever the number of pairs per cluster, the dispersion of the design is bounded below by the between-cluster variance.
\end{corollary}

\subsection{The exact bootstrap variance law}

\begin{theorem}[Resample marginalisation]\label{thm:marg}
For any array $F:\{1,\dots,m\}^2\to\mathbb{R}$,
\[
\sum_{s:[m]\to[m]}\ \prod_{i=1}^m F(i,s(i)) \;=\; \prod_{i=1}^m\ \sum_{j=1}^m F(i,j).
\]
\end{theorem}
\begin{proof}
Expanding the right-hand product of sums produces exactly one term per choice function $s$.
\end{proof}

\begin{corollary}[One coordinate]\label{cor:one}
$\sum_s g(s(k)) = m^{\,m-1}\sum_j g(j)$.
\end{corollary}
\begin{proof}
Apply Theorem~\ref{thm:marg} with $F(i,\cdot) = g$ at $i=k$ and $F(i,\cdot)\equiv1$ otherwise; the right side is $\bigl(\sum_j g(j)\bigr)m^{m-1}$.
\end{proof}

\begin{corollary}[Two coordinates]\label{cor:two}
For $k\ne l$, $\sum_s g(s(k))h(s(l)) = m^{\,m-2}\bigl(\sum_j g(j)\bigr)\bigl(\sum_j h(j)\bigr)$.
\end{corollary}

\begin{lemma}[Recentring]\label{lem:recentre}
$\bar c^{(s)} - \bar c = \frac1m\sum_k (c_{s(k)} - \bar c)$.
\end{lemma}

\begin{theorem}[Exact bootstrap variance law]\label{thm:bootvar}
For any cluster values $c_1,\dots,c_m$ and every $m\ge1$,
\[
\Var_{\mathrm{boot}}(c) \;=\; \frac{\Var(c)}{m}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Put $d_i = c_i - \bar c$, so $\sum_i d_i = 0$ and $\sum_i d_i^2 = m\Var(c)$. By Lemma~\ref{lem:recentre},
\[
m^m\Var_{\mathrm{boot}}(c) = \frac{1}{m^2}\sum_s\Bigl(\sum_k d_{s(k)}\Bigr)^2
= \frac{1}{m^2}\Bigl[\sum_k\sum_s d_{s(k)}^2 + \sum_{k\ne l}\sum_s d_{s(k)}d_{s(l)}\Bigr].
\]
By Corollary~\ref{cor:one} the diagonal term is $m\cdot m^{m-1}\sum_i d_i^2 = m^m\sum_i d_i^2$; by Corollary~\ref{cor:two} each off-diagonal term is $m^{m-2}(\sum_i d_i)^2 = 0$. Hence $\Var_{\mathrm{boot}}(c) = \frac1{m^2}\sum_i d_i^2 = \Var(c)/m$.
\end{proof}

\begin{theorem}[Applied to the two-level design]\label{thm:clusterboot}
With $c_i = \bar x_i$ the cluster means, $\Var_{\mathrm{boot}}(\bar x_\cdot) = V_{\mathrm{between}}/m$. The within-cluster dispersion --- hence the pair count $n$ --- does not appear.
\end{theorem}

\begin{corollary}
$\Var_{\mathrm{boot}}(\bar x_\cdot)\le V_{\mathrm{total}}/m$, with equality exactly when the design has no within-cluster dispersion.
\end{corollary}

\begin{theorem}[Design rule]\label{thm:designrule}
For any target standard error $t$,
$\Var_{\mathrm{boot}}(c) \le t^2 \iff \Var(c)\le m t^2 \iff m \ge \Var(c)/t^2$.
The pair count is irrelevant; reducing the standard error by a factor $\rho$ costs a factor $\rho^2$ in clusters.
\end{theorem}

\begin{theorem}[Non-degeneracy]
$\Var_{\mathrm{boot}}(c) > 0$ as soon as two clusters carry different values, and $\Var_{\mathrm{boot}}(c) = 0$ for a constant cluster population. The criterion is sharp.
\end{theorem}

\subsection{Stratification: removing the between-cluster variance exactly}

\begin{definition}
For a finite population $\Omega$, a statistic $f:\Omega\to\mathbb{Q}$ and a stratifying map $\kappa:\Omega\to K$, write $\Omega_c = \kappa^{-1}(c)$, $\bar f_c$ for the mean of $f$ on $\Omega_c$, and
\[
\SSq_{\mathrm{tot}} = \sum_\omega (f(\omega)-\bar f)^2,\quad
\SSq_{\mathrm{within}} = \sum_c\sum_{\omega\in\Omega_c}(f(\omega)-\bar f_c)^2,\quad
\SSq_{\mathrm{between}} = \sum_c |\Omega_c|(\bar f_c - \bar f)^2 .
\]
\end{definition}

\begin{theorem}[General one-way decomposition]\label{thm:strat}
For an arbitrary finite population, an arbitrary real-valued statistic and an arbitrary stratifying map whose image lies in the index set,
$\SSq_{\mathrm{tot}} = \SSq_{\mathrm{within}} + \SSq_{\mathrm{between}}$.
No balance assumption is needed; fibres may have any sizes, including zero.
\end{theorem}

\begin{corollary}\label{cor:strat}
$\SSq_{\mathrm{within}}\le\SSq_{\mathrm{tot}}$ and $\SSq_{\mathrm{between}}\le\SSq_{\mathrm{tot}}$. If $f$ is constant on each fibre then $\SSq_{\mathrm{within}} = 0$ and $\SSq_{\mathrm{between}} = \SSq_{\mathrm{tot}}$.
\end{corollary}

Apply this to the bias $\Pi$, stratified by the \emph{quadratic-class count} $\kappa(e) = \#\{i:\varepsilon_i = +1\}$.

\begin{lemma}\label{lem:classcount}
$\Pi(e) = 2^k$ if $\kappa(e)=k$ and $\Pi(e)=0$ otherwise; in particular $\Pi$ is a function of $\kappa$ alone.
\end{lemma}

\begin{proposition}
$\SSq_{\mathrm{tot}}(\Pi) = 2^k(2^k-1)$, consistent with $\Var(\Pi) = 2^k-1$ over a population of size $2^k$.
\end{proposition}

\begin{theorem}[Quadratic-class stratification is exact]\label{thm:stratexact}
Stratifying by $\kappa$ leaves $\SSq_{\mathrm{within}} = 0$ and $\SSq_{\mathrm{between}} = 2^k(2^k-1)$: the class-count stratification accounts for the entire between-modulus variance.
\end{theorem}
\begin{proof}
Lemma~\ref{lem:classcount} makes $\Pi$ fibre-wise constant; apply Corollary~\ref{cor:strat}.
\end{proof}

\begin{proposition}[Non-vacuity]
For the trivial one-stratum design, $\SSq_{\mathrm{between}} = 0$ and $\SSq_{\mathrm{within}} = 2^k(2^k-1) > 0$ for $k\ge1$.
\end{proposition}

\section{Power arithmetic, and pooling}

\subsection{The $\sqrt m$ law and the cost of the next run}

\begin{definition}
For a calibration constant $c>0$, the cluster-bootstrap half-width on $m$ clusters is $H(c,m) = c/\sqrt m$.
\end{definition}

\begin{lemma}\label{lem:sqrtm}
For $c,\delta>0$ and $m\ge1$: $H(c,m)<\delta \iff m > (c/\delta)^2$. Moreover $H$ is antitone in $m$ and $H(c,4m) = H(c,m)/2$.
\end{lemma}

The realised run has $m=128$ and half-width $0.04555$, so $c_{\mathrm{cal}} = 0.04555\sqrt{128}$ with $c_{\mathrm{cal}}^2 \approx 0.26561$. To resolve a $1\%$ deviation at the point estimate $0.99$, the half-width must fall below $0.01$.

\begin{theorem}[Ten times is not enough]
For $1\le m \le 1280$, $H(c_{\mathrm{cal}},m)\ge 0.01$.
\end{theorem}

\begin{theorem}[Thirty times suffices]
For $m\ge 3840$, $H(c_{\mathrm{cal}},m) < 0.01$.
\end{theorem}

\begin{theorem}[Exact threshold]\label{thm:threshold}
$H(c_{\mathrm{cal}},2656)<0.01$ and $H(c_{\mathrm{cal}},2655)\not<0.01$. The least sufficient cluster count is $2656$, i.e.\ $20.75\times$ the realised $128$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:sqrtm} the criterion is $m > c_{\mathrm{cal}}^2/10^{-4} = 0.04555^2\cdot128\cdot10^4 = 2655.6\ldots$; hence the least integer is $2656$, and $1280 < 2656 \le 3840$.
\end{proof}

\begin{proposition}[Diagnostic on the pilot effect size]
For any $c_0 \le 0.947$, $c_0 + 0.04555 < 1$. Had the true ratio been at the pilot's point estimate, the replication --- at its realised precision --- would have produced an interval excluding $1$. It did not.
\end{proposition}

\subsection{Inverse-variance pooling}

\begin{definition}
For variances $v_1,v_2>0$, set $V(v_1,v_2) = \dfrac{v_1v_2}{v_1+v_2}$ and $w^\star = \dfrac{v_2}{v_1+v_2}$.
\end{definition}

\begin{theorem}[Optimality]\label{thm:pooloptimal}
For every $w\in\mathbb{R}$, the combination $wx_1+(1-w)x_2$ of independent estimates has variance $w^2v_1+(1-w)^2v_2 \ge V(v_1,v_2)$, with equality if and only if $w = w^\star$.
\end{theorem}
\begin{proof}
$w^2v_1+(1-w)^2v_2 - V(v_1,v_2) = (v_1+v_2)(w-w^\star)^2 \ge 0$.
\end{proof}

\begin{corollary}
$V(v_1,v_2) < \min(v_1,v_2)$: pooling is a strict gain over either input.
\end{corollary}

In half-width form, put $\mathcal{H}(h_1,h_2) = \dfrac{h_1h_2}{\sqrt{h_1^2+h_2^2}}$ and $P = \lambda p_1 + (1-\lambda)p_2$ with $\lambda = h_2^2/(h_1^2+h_2^2)$.

\begin{theorem}[Matched precisions give exactly $\sqrt2$]
$\mathcal H(h,h) = h/\sqrt2$.
\end{theorem}

\begin{theorem}[The $\sqrt2$ ceiling]\label{thm:ceiling}
For all $h_1,h_2>0$, $\dfrac{\min(h_1,h_2)}{\sqrt2}\le \mathcal H(h_1,h_2)$, with equality if and only if $h_1=h_2$; the inequality is strict whenever $h_1\ne h_2$.
\end{theorem}
\begin{proof}
Assume w.l.o.g.\ $h_2 = \min$. Squaring, the claim is $h_2^2/2 \le h_1^2h_2^2/(h_1^2+h_2^2)$, i.e.\ $h_1^2+h_2^2 \le 2h_1^2$, i.e.\ $h_2\le h_1$; equality iff $h_1=h_2$.
\end{proof}

\subsection{The pooled verdict for the two runs}

With $p_1 = 0.95095$, $h_1 = 0.08795$ (pilot) and $p_2 = 0.96455$, $h_2 = 0.04555$ (replication):

\begin{theorem}[Pooling does not resurrect the drift]
$|1-P| \le \mathcal H(h_1,h_2)$: the inverse-variance pooled $95\%$ interval still covers $1$.
\end{theorem}

\begin{theorem}[But only just]
$P + \mathcal H(h_1,h_2) < 1.0022$; numerically $P\approx 0.96167$ and $\mathcal H\approx0.04045$.
\end{theorem}

\begin{theorem}[$\sqrt2$ is not realised here]
Since $h_1/h_2 \approx 1.93 \ne 1$, Theorem~\ref{thm:ceiling} gives $h_2/\sqrt2 < \mathcal H(h_1,h_2)$ strictly.
\end{theorem}

\begin{theorem}[The realised gain is small]
$0.88\,h_2 < \mathcal H(h_1,h_2)$: pooling with the noisier pilot improves on the replication alone by under $12\%$.
\end{theorem}

\begin{theorem}[The quoted joint point is the equal-weight one]
With reported point estimates $0.947$ and $0.99$, the equal-weight average is $0.9685$ while the inverse-variance pooled point $P_{\mathrm{pts}}$ satisfies $0.98 < P_{\mathrm{pts}} < 0.9810$. Consequently $|1-P_{\mathrm{pts}}| < |1-0.9685|$: precision weighting moves the joint point strictly closer to the null.
\end{theorem}

\section{Audit of two run defects}

\subsection{The round-to-four display defect}

The output writer stored the candidate smooth rate rounded to four decimals, $\mathrm{store}_4(x) = \lfloor 10^4x+\tfrac12\rfloor/10^4$; the true rate is of order $3\times10^{-5}$.

\begin{proposition}[The stored zero is information-free]
For $0\le x<5\times10^{-5}$, $\mathrm{store}_4(x)=0$. Hence $\mathrm{store}_4$ is not injective on the relevant range, and the stored $0.0$ carries no information beyond membership in $[0,5\times10^{-5})$.
\end{proposition}

\begin{proposition}[CI-implied recovery]
If $r\in I$ and the control rate is $\rho\ge0$, then the candidate rate $r\rho$ lies in $[\rho\ell(I),\rho h(I)]$. With $I = [0.8571,1.1488]$ and $\rho = 3.1\times10^{-5}$,
\[
r\rho \in [\,2.65701\times10^{-5},\ 3.56128\times10^{-5}\,].
\]
In particular $r\rho>0$, so the stored $0.0$ is provably not the measured value.
\end{proposition}

\begin{proposition}[The circulated bracket is not an enclosure]
The bracket $[2.66\times10^{-5},3.56\times10^{-5}]$ has both endpoints rounded \emph{inwards} and fails to contain the CI-implied range. The outward-rounded $[2.65\times10^{-5},3.57\times10^{-5}]$ is a valid enclosure.
\end{proposition}

\subsection{The degenerate smoke-leg bootstrap}

Call a cluster an \emph{event cluster} if it carries at least one smooth hit; a resample is \emph{degenerate} exactly when it selects no event cluster, since then the ratio is $0/0$.

\begin{theorem}[Exact count]
For any set $H$ of clusters with $|H|=h$, exactly $(m-h)^m$ of the $m^m$ resamples avoid $H$.
\end{theorem}
\begin{proof}
Such resamples are exactly the functions $[m]\to[m]\setminus H$.
\end{proof}

\begin{corollary}
The degenerate fraction is exactly $(1-h/m)^m$.
\end{corollary}

\begin{theorem}[Uniform exponential bound]
$(1-h/m)^m \le e^{-h}$, uniformly in $m$.
\end{theorem}

\begin{corollary}[One event cluster suffices]
If $h\ge1$, the non-degenerate fraction is at least $1-e^{-1}\approx 0.632$, whatever the cluster count.
\end{corollary}

\begin{theorem}[Diagnosis]
Observing fewer than $100$ non-degenerate resamples out of $2000$ (a fraction below $0.05\ll0.632$) is impossible with even one event cluster. Hence the smoke-leg population contained no smooth hit at all: $h=0$, and the degenerate fraction is exactly $1$. Its interval carries no information about the ratio rather than carrying a wide one.
\end{theorem}

\section{Verdict and interpretation}

\textbf{Verdict: the null branch, with no gate armed.}
\begin{enumerate}
\item At the pre-registered primary threshold, the interval $[0.8571,1.1488]$ covers $1$.
\item At the better-powered secondary threshold, $r\approx0.99$ with interval $[0.919,1.0101]$ over $128$ clusters and $19.2\times10^6$ pairs. The edge deliverable $0.081$ strictly tightens the pilot's $0.137$, with both precision and drift improving.
\item Pooled with the pilot, the joint interval still covers $1$, upper edge below $1.0022$; the precision-weighted joint point is $\approx0.981$, closer to the null than the equal-weight $0.9685$.
\item The pilot's direction stability across four split-halves has null probability $1/8$.
\end{enumerate}

The sub-unit drift does not replicate downward. We downgrade it from a banked tension to an open question at reduced weight. Decisive resolution requires $2656$ clusters (Theorem~\ref{thm:threshold}).

No barrier is breached and no complexity constant is shaved. What the null does is \emph{strengthen} the randomness heuristic for shifted squares into the Dickman approach zone through $u\approx11.7$.

\section{Limitations}

\begin{enumerate}
\item \textbf{Power.} Realised throughput ($76.4\,\mu$s per value; wall time $1467$\,s against a $1104$\,s estimate) capped this run at roughly $1\times$ the pilot's power rather than the aspirational $10\!-\!30\times$; its role was reframed in advance as scoping and as the fresh-seed replication gate.
\item \textbf{Model idealisation.} Theorem~\ref{thm:bias} is derived in an idealised sign model; the constant should be read as a scaling statement, supported by the exact multiplicativity of Corollary~\ref{cor:crtprod}.
\item \textbf{The finite-to-full passage.} Corollary~\ref{cor:crtprod} removes the independence heuristic but not the passage from a finite prime set to full smoothness.
\item \textbf{Data loss.} The candidate hit rate is reconstructed from the ratio interval rather than measured.
\item \textbf{Two thresholds.} The tighter conclusion comes from the secondary threshold, whose reduced weight was declared in advance and is maintained.
\end{enumerate}

\section{Future directions}

\textbf{A. The decisive run.} Theorem~\ref{thm:threshold} gives the price: $2656$ clusters. Because the pair count is provably not a power lever (Theorem~\ref{thm:clusterboot}), the entire budget should go into distinct moduli.

\textbf{B. Stratified design.} Theorem~\ref{thm:stratexact} shows that stratifying the modulus population by quadratic-class count removes the whole between-modulus dispersion in the idealised model --- the cheapest available power multiplier, orthogonal to increasing $m$.

\textbf{C. Budget allocation.} Given a fixed budget split between a new run and re-analysis of an old one, Theorem~\ref{thm:pooloptimal} determines the allocation minimising the pooled half-width.

\textbf{D. Attacking the remaining heuristic.} A rigorous version of the finite-to-full passage for shifted squares --- even one-sided --- would convert the sieve complexity analysis from heuristic to unconditional in this regime.

\textbf{E. Higher $u$.} Each additional unit of $u$ costs event rate exponentially, which by Theorem~\ref{thm:designrule} costs clusters quadratically in the target precision.

\section{Conclusion}

A rumour of non-randomness in the smoothness of $j^2-N$ at band 9 has been tested against an independent population of $128$ moduli and $19.2$ million matched pairs, and has not survived. The measured ratio is $0.99$ with the tightest interval yet obtained in this regime; pooling with the original pilot leaves the joint interval covering the null; the pilot's most persuasive diagnostic is worth $1/8$; and the arithmetic reason for the null is visible at a single prime, where the candidate density $(1+\Leg{N}{p})/p$ averages to exactly $1/p$ over the two quadratic classes.

Around that null we have built exact finite-sample infrastructure: an identity separating what an interval delivers into precision and drift; an exact variance law for cluster resampling; an exact ANOVA accounting making cluster inference forced and quadratic-class stratification complete; the correct sharp form of the pooling gain; and an exact degeneracy analysis reading an anomalous output as a statement about the population. The single most useful number produced is $2656$: the cluster count at which this question stops being open.

